"""Additive company profiles; no editorial facts are generated by migration."""
from sqlalchemy import inspect,text
from .models import Manufacturer
from .source_policy import is_internal_source

PROFILE_FIELDS=('legal_name','description','description_author','description_source_url','description_license_url','headquarters','founders','logo_url','logo_author','logo_license','logo_license_url','logo_source_url')
DATE_FIELDS=('founded','ceased')


def ensure_schema(engine):
    with engine.begin() as conn:
        if engine.dialect.name=='postgresql':conn.execute(text('SELECT pg_advisory_xact_lock(68484931)'))
        columns={c['name'] for c in inspect(conn).get_columns('manufacturers')}
        for column in Manufacturer.__table__.columns:
            if column.name not in columns:
                # All additions are nullable. Existing values and identities stay intact.
                datatype=column.type.compile(dialect=engine.dialect)
                conn.exec_driver_sql(f'ALTER TABLE manufacturers ADD COLUMN {column.name} {datatype}')


def date_label(value,precision):
    if value is None:return None
    return value.isoformat()[:{'year':4,'month':7}.get(precision,10)]


def profile_data(item):
    return {**{field:getattr(item,field) for field in PROFILE_FIELDS},
        **{field:date_label(getattr(item,field),getattr(item,field+'_precision')) for field in DATE_FIELDS},
        'source_ids':[s.id for s in item.sources],
        'sources':[{'id':s.id,'title':s.title,'url':s.url,'author':s.author,'publisher':s.publisher}
            for s in sorted(item.sources,key=lambda s:s.id) if not is_internal_source(s)]}
